/* Recipes: second batch (November 2026). Everyday dishes UK home growers look for most. */
export const BATCH_TWO = [
  /* Soups */
  { id:"roast-tomato-soup", title:"Roast Tomato Soup", time:"1 hr", serves:"4", uses:["tomato","onion","garlic","basil"],
    ingredients:[["tomato","Ripe tomatoes, halved","1 kg"],["onion","Onion, cut into wedges","1"],["garlic","Garlic cloves, unpeeled","4"],["olive oil","Olive oil","3 tbsp"],["stock","Vegetable stock","500 ml"],["basil","Basil leaves","small handful"],["sugar","Sugar (if needed)","pinch"]],
    steps:["Heat the oven to 200°C (180°C fan). Spread the tomatoes, onion and garlic in a roasting tin, drizzle with the oil and season with salt and pepper.","Roast for 40 minutes until the tomatoes are soft and starting to char at the edges.","Squeeze the garlic out of its skins and tip everything, including the juices, into a pan with the stock.","Simmer for 5 minutes, add most of the basil, then blend until smooth.","Taste and add a pinch of sugar if the tomatoes were a little sharp. Serve with the rest of the basil torn over the top."],
    tips:["Roasting brings out the sweetness, so this works well even with tomatoes that are not perfectly ripe.","It freezes well. Cool it, then freeze in portions for up to 3 months."] },
  { id:"carrot-coriander-soup", title:"Carrot & Coriander Soup", time:"35 min", serves:"4", uses:["carrot","onion","coriander"],
    ingredients:[["carrot","Carrots, sliced","600 g"],["onion","Onion, chopped","1"],["butter","Butter or oil","1 tbsp"],["spice","Ground coriander","1 tsp"],["stock","Vegetable stock","1 litre"],["coriander","Fresh coriander, chopped","large handful"]],
    steps:["Melt the butter in a large pan and cook the onion gently for 5 minutes until soft.","Stir in the ground coriander and cook for 1 minute.","Add the carrots and stock, bring to the boil and simmer for 20 minutes until the carrots are very soft.","Add most of the fresh coriander, including the stalks, and blend until smooth.","Season to taste and serve with the rest of the coriander scattered over."],
    tips:["Use the coriander stalks as well as the leaves. They have lots of flavour and blend in easily.","Older, woody carrots are fine here. Cut out any tough core before cooking."] },
  { id:"courgette-basil-soup", title:"Courgette & Basil Soup", time:"30 min", serves:"4", uses:["courgette","onion","garlic","basil"],
    ingredients:[["courgette","Courgettes, chopped","4 medium (about 800 g)"],["onion","Onion, chopped","1"],["garlic","Garlic cloves, sliced","2"],["olive oil","Olive oil","2 tbsp"],["stock","Vegetable stock","750 ml"],["basil","Basil leaves","large handful"],["parmesan","Parmesan, grated, to serve","optional"]],
    steps:["Warm the oil in a large pan and cook the onion for 5 minutes until soft. Add the garlic and cook for 1 minute more.","Add the courgettes and cook for 5 minutes, stirring now and then.","Pour in the stock and simmer for 10 minutes until the courgettes are tender.","Take off the heat, add the basil and blend until smooth.","Season and serve with a little grated parmesan if you like."],
    tips:["A great way to use courgettes that have grown big. Scoop out the seedy middle of very large ones first.","Add the basil at the end so it stays bright green."] },
  { id:"french-onion-soup", title:"French Onion Soup", time:"1 hr 15 min", serves:"4", uses:["onion","thyme","bay"],
    ingredients:[["onion","Onions, thinly sliced","1 kg"],["butter","Butter","50 g"],["sugar","Sugar","1 tsp"],["flour","Plain flour","1 tbsp"],["wine","Dry white wine (optional)","150 ml"],["stock","Beef or vegetable stock","1.2 litres"],["thyme","Thyme sprigs","4"],["bay","Bay leaves","2"],["bread","Baguette slices","8"],["cheddar","Gruyère or mature cheddar, grated","100 g"]],
    steps:["Melt the butter in a large pan, add the onions and sugar and cook over a low heat for 40 to 45 minutes, stirring often, until deep golden and sticky.","Stir in the flour and cook for 1 minute, then add the wine if using and let it bubble for 2 minutes.","Add the stock, thyme and bay leaves and simmer for 20 minutes. Season, then remove the herbs.","Toast the bread, top with the cheese and grill until bubbling.","Ladle the soup into bowls and float the cheesy toasts on top."],
    tips:["Do not rush the onions. Slow cooking is what gives the soup its rich, sweet flavour.","Stored onions that have started to sprout are fine to use. Just cut out the green shoot."] },
  { id:"curried-parsnip-soup", title:"Curried Parsnip Soup", time:"40 min", serves:"4", uses:["parsnip","onion","garlic"],
    ingredients:[["parsnip","Parsnips, peeled and chopped","600 g"],["onion","Onion, chopped","1"],["garlic","Garlic cloves, crushed","2"],["oil","Oil","1 tbsp"],["spice","Mild curry powder","2 tsp"],["stock","Vegetable stock","1 litre"],["milk","Milk or single cream","100 ml"]],
    steps:["Heat the oil in a large pan and cook the onion for 5 minutes. Add the garlic and curry powder and cook for 1 minute.","Add the parsnips and stock and bring to the boil.","Simmer for 20 to 25 minutes until the parsnips are very soft.","Blend until smooth, then stir in the milk or cream and warm through.","Season with salt and pepper and serve with warm bread."],
    tips:["Parsnips taste sweeter after a frost, so this soup is even better in mid-winter.","Cut out any woody core from large parsnips before cooking."] },
  { id:"celeriac-apple-soup", title:"Celeriac & Apple Soup", time:"40 min", serves:"4", uses:["celeriac","apple","onion","thyme"],
    ingredients:[["celeriac","Celeriac, peeled and chopped","1 medium (about 700 g)"],["apple","Eating apples, peeled and chopped","2"],["onion","Onion, chopped","1"],["butter","Butter","25 g"],["thyme","Thyme leaves","1 tsp"],["stock","Vegetable or chicken stock","1 litre"],["cream","Single cream (optional)","50 ml"]],
    steps:["Melt the butter in a large pan and cook the onion gently for 5 minutes.","Add the celeriac, apples and thyme and stir for 2 minutes.","Pour in the stock, bring to the boil and simmer for 25 minutes until the celeriac is tender.","Blend until very smooth and season to taste.","Serve with a swirl of cream and a few extra thyme leaves."],
    tips:["Celeriac browns quickly once peeled, so drop the pieces straight into the pan.","A sharp apple balances the earthy flavour of the celeriac nicely."] },
  { id:"garden-minestrone", title:"Garden Minestrone", time:"45 min", serves:"6", uses:["carrot","celery","onion","courgette","french-bean","cabbage","tomato"],
    ingredients:[["olive oil","Olive oil","2 tbsp"],["onion","Onion, chopped","1"],["carrot","Carrots, diced","2"],["celery","Celery sticks, diced","2"],["courgette","Courgette, diced","1"],["tomato","Tomatoes, chopped (or a 400 g tin)","400 g"],["stock","Vegetable stock","1.5 litres"],["pasta","Small pasta shapes","75 g"],["french-bean","French beans, cut short","100 g"],["cabbage","Cabbage or kale, shredded","2 handfuls"],["parmesan","Parmesan, to serve","optional"]],
    steps:["Heat the oil in a large pan and cook the onion, carrots and celery for 10 minutes until softened.","Add the courgette and tomatoes and cook for 5 minutes.","Pour in the stock and bring to the boil, then add the pasta and simmer for 6 minutes.","Add the beans and cabbage and cook for 5 more minutes until everything is tender.","Season well and serve with grated parmesan."],
    tips:["Use whatever is ready in the garden. Peas, spinach, leeks and chard all work well.","Add the pasta just before serving if you plan to keep leftovers, or it will soak up the liquid."] },
  { id:"beetroot-borscht", title:"Beetroot Borscht", time:"1 hr", serves:"6", uses:["beetroot","cabbage","carrot","onion","potato","dill"],
    ingredients:[["beetroot","Raw beetroot, peeled and grated","500 g"],["carrot","Carrot, grated","1"],["onion","Onion, chopped","1"],["oil","Oil","2 tbsp"],["stock","Vegetable or beef stock","1.5 litres"],["cabbage","White cabbage, shredded","1/4"],["potato","Potato, diced","1 large"],["vinegar","Red wine vinegar","1 tbsp"],["dill","Dill, chopped","small handful"],["yoghurt","Soured cream or yoghurt, to serve","4 tbsp"]],
    steps:["Heat the oil in a large pan and cook the onion and carrot for 5 minutes.","Add the beetroot and cook for 5 minutes more, stirring.","Pour in the stock, add the potato and simmer for 20 minutes.","Add the cabbage and simmer for 10 minutes until tender.","Stir in the vinegar, season and serve with a spoonful of soured cream and plenty of dill."],
    tips:["Wear gloves when grating beetroot, or rub your hands with lemon juice afterwards to remove the stains.","The vinegar keeps the colour a deep, bright red."] },

  /* Mains */
  { id:"courgette-lemon-pasta", title:"Courgette, Lemon & Mint Pasta", time:"20 min", serves:"2", uses:["courgette","mint","garlic"],
    ingredients:[["pasta","Spaghetti or linguine","200 g"],["courgette","Courgettes, grated","2 medium"],["garlic","Garlic clove, crushed","1"],["olive oil","Olive oil","2 tbsp"],["lemon","Lemon, zest and juice","1"],["mint","Mint, chopped","small handful"],["parmesan","Parmesan, grated","40 g"]],
    steps:["Cook the pasta in salted boiling water according to the packet.","Meanwhile, warm the oil in a large frying pan and cook the garlic for 30 seconds.","Add the courgettes and cook for 4 to 5 minutes until soft.","Drain the pasta, keeping a cup of the cooking water, and add it to the pan with the lemon zest, juice, mint and most of the parmesan.","Toss together, adding a splash of the pasta water to make it glossy. Season and serve with the rest of the parmesan."],
    tips:["Grating the courgettes means they cook in minutes and coat the pasta well.","Basil or parsley work just as well as mint."] },
  { id:"cottage-pie", title:"Cottage Pie with Root Veg Mash", time:"1 hr 30 min", serves:"4–6", uses:["potato","parsnip","carrot","onion","thyme"],
    ingredients:[["oil","Oil","1 tbsp"],["onion","Onion, chopped","1"],["carrot","Carrots, diced","2"],["mince","Beef mince","500 g"],["flour","Plain flour","1 tbsp"],["stock","Beef stock","300 ml"],["worcestershire","Worcestershire sauce","1 tbsp"],["thyme","Thyme leaves","1 tsp"],["potato","Floury potatoes, peeled and chopped","700 g"],["parsnip","Parsnips, peeled and chopped","300 g"],["butter","Butter","40 g"],["milk","Milk","splash"]],
    steps:["Heat the oil and cook the onion and carrots for 8 minutes. Add the mince and brown it, breaking it up as it cooks.","Stir in the flour, then add the stock, Worcestershire sauce and thyme. Simmer for 25 minutes until thick, and season.","Meanwhile, boil the potatoes and parsnips for 15 to 20 minutes until tender. Drain and mash with the butter and milk.","Heat the oven to 200°C (180°C fan). Spoon the mince into an ovenproof dish and top with the mash, roughing it up with a fork.","Bake for 25 to 30 minutes until golden and bubbling at the edges."],
    tips:["Swede or celeriac can replace some of the parsnip in the mash.","For a vegetarian version, use green lentils and chopped mushrooms instead of mince."] },
  { id:"leek-cheese-tart", title:"Leek & Cheese Tart", time:"1 hr", serves:"6", uses:["leek","thyme"],
    ingredients:[["pastry","Ready-rolled shortcrust pastry","320 g sheet"],["butter","Butter","25 g"],["leek","Leeks, sliced","3 medium"],["thyme","Thyme leaves","1 tsp"],["egg","Eggs","3"],["cream","Double cream or milk","200 ml"],["cheddar","Mature cheddar, grated","100 g"],["mustard","Wholegrain mustard","1 tsp"]],
    steps:["Heat the oven to 200°C (180°C fan). Line a 23 cm tart tin with the pastry, prick the base and bake for 15 minutes.","Meanwhile, melt the butter and cook the leeks gently with the thyme for 10 minutes until soft. Season.","Whisk the eggs, cream and mustard together and stir in most of the cheese.","Spread the leeks in the pastry case, pour over the egg mixture and scatter with the rest of the cheese.","Turn the oven down to 180°C (160°C fan) and bake for 25 to 30 minutes until just set with a slight wobble. Cool for 10 minutes before slicing."],
    tips:["Wash sliced leeks in a bowl of water to remove any soil trapped between the layers, then drain well.","Good warm or cold, so it is ideal for picnics and lunchboxes."] },
  { id:"spinach-ricotta-pasta-bake", title:"Spinach & Ricotta Pasta Bake", time:"45 min", serves:"4", uses:["spinach","garlic","tomato","basil"],
    ingredients:[["pasta","Penne or rigatoni","300 g"],["spinach","Spinach","300 g"],["ricotta","Ricotta","250 g"],["garlic","Garlic cloves, crushed","2"],["olive oil","Olive oil","1 tbsp"],["tomato","Tomatoes, chopped (or a 400 g tin)","400 g"],["basil","Basil, torn","small handful"],["mozzarella","Mozzarella, torn","1 ball"]],
    steps:["Heat the oven to 200°C (180°C fan). Cook the pasta for 2 minutes less than the packet says, then drain.","Warm the oil and cook the garlic for 30 seconds, then add the tomatoes and simmer for 10 minutes. Stir in the basil and season.","Wilt the spinach in a pan with a splash of water, squeeze out the liquid, chop and mix with the ricotta.","Stir the pasta into the tomato sauce, then fold through spoonfuls of the spinach mixture.","Tip into an ovenproof dish, top with mozzarella and bake for 20 minutes until golden and bubbling."],
    tips:["Perpetual spinach or chard leaves work just as well as spinach.","Squeeze the cooked spinach hard, or the bake will be watery."] },
  { id:"cauliflower-potato-curry", title:"Cauliflower & Potato Curry", time:"40 min", serves:"4", uses:["cauliflower","potato","onion","garlic","chilli","tomato","coriander"],
    ingredients:[["oil","Oil","2 tbsp"],["onion","Onion, chopped","1"],["garlic","Garlic cloves, crushed","3"],["ginger","Fresh ginger, grated","thumb-sized piece"],["chilli","Green chilli, sliced","1"],["spice","Curry powder or garam masala","2 tbsp"],["tomato","Tomatoes, chopped (or a 400 g tin)","400 g"],["potato","Potatoes, cut into chunks","400 g"],["cauliflower","Cauliflower, in florets","1 medium"],["coconut milk","Coconut milk","400 ml tin"],["coriander","Fresh coriander","handful"]],
    steps:["Heat the oil and cook the onion for 8 minutes until golden. Add the garlic, ginger and chilli and cook for 1 minute.","Stir in the curry powder and cook for 1 minute, then add the tomatoes.","Add the potatoes and coconut milk, cover and simmer for 10 minutes.","Add the cauliflower and simmer for another 12 to 15 minutes until everything is tender.","Season, scatter with coriander and serve with rice or naan."],
    tips:["Peas, spinach or chard can go in for the last few minutes.","Like most curries, it tastes even better the next day."] },
  { id:"kale-garlic-spaghetti", title:"Kale, Garlic & Chilli Spaghetti", time:"20 min", serves:"2", uses:["kale","garlic","chilli"],
    ingredients:[["pasta","Spaghetti","200 g"],["kale","Kale, stalks removed, shredded","150 g"],["olive oil","Olive oil","3 tbsp"],["garlic","Garlic cloves, thinly sliced","3"],["chilli","Red chilli, chopped (or chilli flakes)","1"],["lemon","Lemon, zest and juice","1/2"],["parmesan","Parmesan, grated","40 g"]],
    steps:["Cook the spaghetti in salted boiling water. Add the kale for the last 3 minutes.","Meanwhile, warm the oil gently in a large frying pan and cook the garlic and chilli for 2 minutes until the garlic is just turning golden.","Drain the pasta and kale, keeping a cup of the cooking water.","Toss everything in the frying pan with the lemon zest and juice, most of the parmesan and a splash of the pasta water.","Season and serve with the rest of the parmesan."],
    tips:["Any kale works, as do sprout tops, cabbage or chard.","Keep the heat low for the garlic. It turns bitter if it burns."] },
  { id:"pea-broad-bean-risotto", title:"Pea, Broad Bean & Mint Risotto", time:"35 min", serves:"4", uses:["pea","broad-bean","mint","onion"],
    ingredients:[["butter","Butter","40 g"],["onion","Onion, finely chopped","1"],["rice","Risotto rice","300 g"],["wine","Dry white wine (optional)","100 ml"],["stock","Hot vegetable stock","1.2 litres"],["pea","Peas, fresh or frozen","200 g"],["broad-bean","Broad beans, shelled","200 g"],["mint","Mint, chopped","small handful"],["parmesan","Parmesan, grated","50 g"],["lemon","Lemon zest","1/2"]],
    steps:["Melt half the butter and cook the onion gently for 5 minutes.","Add the rice and stir for 1 minute, then add the wine and let it bubble away.","Add the stock a ladle at a time, stirring often and waiting until each ladle is absorbed before adding the next. This takes about 20 minutes.","Add the peas and broad beans for the last 4 minutes.","Take off the heat and stir in the rest of the butter, the parmesan, mint and lemon zest. Season, cover and leave for 2 minutes before serving."],
    tips:["Pop large broad beans out of their grey skins after cooking for the brightest colour and softest texture.","The risotto should be loose and creamy, so add a little more stock if it looks stiff."] },
  { id:"garden-bean-chilli", title:"Three-Bean Garden Chilli", time:"50 min", serves:"4–6", uses:["chilli","sweet-pepper","onion","garlic","tomato","borlotti-bean","coriander"],
    ingredients:[["oil","Oil","2 tbsp"],["onion","Onion, chopped","1"],["sweet-pepper","Sweet peppers, chopped","2"],["garlic","Garlic cloves, crushed","3"],["chilli","Chillies, chopped","1–2"],["spice","Ground cumin and smoked paprika","1 tsp each"],["tomato","Tomatoes, chopped (or 2 x 400 g tins)","800 g"],["borlotti-bean","Cooked borlotti beans (or a tin)","400 g"],["beans","Tins of kidney beans and black beans, drained","1 each"],["coriander","Coriander, to serve","handful"]],
    steps:["Heat the oil and cook the onion and peppers for 8 minutes until soft.","Add the garlic, chilli and spices and cook for 1 minute.","Add the tomatoes and all the beans with 150 ml water.","Simmer for 30 minutes, stirring now and then, until thick.","Season and serve with rice, a spoonful of yoghurt and coriander."],
    tips:["Taste your chillies first. Home-grown ones vary a lot in heat.","Freezes well for up to 3 months."] },
  { id:"pak-choi-noodles", title:"Pak Choi & Ginger Noodles", time:"15 min", serves:"2", uses:["pak-choi","spring-onion","garlic","chilli"],
    ingredients:[["noodles","Egg or rice noodles","2 nests"],["sesame oil","Sesame or vegetable oil","1 tbsp"],["garlic","Garlic cloves, sliced","2"],["ginger","Fresh ginger, cut into thin strips","thumb-sized piece"],["chilli","Red chilli, sliced","1"],["pak-choi","Pak choi, halved or quartered","2 heads"],["soy","Soy sauce","2 tbsp"],["honey","Honey","1 tsp"],["spring-onion","Spring onions, sliced","3"]],
    steps:["Cook the noodles according to the packet, then drain.","Heat the oil in a wok or large frying pan and stir-fry the garlic, ginger and chilli for 1 minute.","Add the pak choi and stir-fry for 2 to 3 minutes until the leaves wilt and the stems are just tender.","Add the noodles, soy sauce and honey and toss until hot.","Serve topped with the spring onions."],
    tips:["Tatsoi, mizuna or Chinese cabbage can be used instead of pak choi.","Add cooked chicken, prawns or tofu to make it more filling."] },
  { id:"bubble-and-squeak", title:"Bubble & Squeak", time:"30 min", serves:"4", uses:["potato","cabbage","brussels-sprouts","onion"],
    ingredients:[["potato","Cooked potatoes, mashed or roughly crushed","500 g"],["cabbage","Cooked cabbage, chopped","150 g"],["brussels-sprouts","Cooked Brussels sprouts, chopped","100 g"],["onion","Onion, finely chopped","1"],["butter","Butter","25 g"],["oil","Oil","1 tbsp"]],
    steps:["Melt half the butter in a large frying pan and cook the onion for 5 minutes until soft.","Mix the onion with the potatoes and greens and season well.","Heat the rest of the butter with the oil in the pan, add the mixture and press it down into a flat cake.","Cook over a medium heat for 8 to 10 minutes until a golden crust forms underneath.","Flip it in sections, cook for another 5 minutes and serve with a fried egg or cold meats."],
    tips:["Perfect for using up leftover vegetables after a roast dinner.","Do not stir it too often. The crispy brown bits are the best part."] },
  { id:"tarragon-chicken", title:"Creamy Tarragon Chicken", time:"35 min", serves:"4", uses:["tarragon","shallot","garlic"],
    ingredients:[["chicken","Chicken thighs or breasts","4"],["oil","Oil","1 tbsp"],["shallot","Shallots, finely chopped","2"],["garlic","Garlic clove, crushed","1"],["wine","Dry white wine (or extra stock)","100 ml"],["stock","Chicken stock","200 ml"],["cream","Double cream or crème fraîche","150 ml"],["mustard","Dijon mustard","1 tsp"],["tarragon","French tarragon, chopped","2 tbsp"]],
    steps:["Season the chicken and brown it in the oil for 5 minutes on each side, then lift it out.","Cook the shallots in the same pan for 3 minutes, then add the garlic for 1 minute.","Add the wine and let it bubble for 2 minutes, then add the stock and return the chicken.","Cover and simmer for 15 minutes until the chicken is cooked through.","Stir in the cream, mustard and tarragon and simmer for 2 minutes. Season and serve with new potatoes or rice."],
    tips:["French tarragon has a much better flavour than Russian tarragon, which is coarse and bitter.","Tarragon is strong, so start with a little and add more to taste."] },
  { id:"thai-green-curry", title:"Thai Green Curry with Garden Veg", time:"30 min", serves:"4", uses:["lemongrass","coriander","chilli","french-bean","pak-choi","garlic"],
    ingredients:[["oil","Oil","1 tbsp"],["paste","Thai green curry paste","3 tbsp"],["lemongrass","Lemongrass stalk, bruised","1"],["garlic","Garlic clove, crushed","1"],["coconut milk","Coconut milk","400 ml tin"],["chicken","Chicken, sliced (or tofu)","400 g"],["french-bean","French beans, halved","150 g"],["pak-choi","Pak choi, sliced","1 head"],["fish sauce","Fish sauce or soy sauce","1 tbsp"],["lime","Lime, juiced","1"],["chilli","Green chilli, sliced, to serve","1"],["coriander","Coriander","handful"]],
    steps:["Heat the oil in a large pan and fry the curry paste, lemongrass and garlic for 1 minute until fragrant.","Pour in the coconut milk and bring to a simmer.","Add the chicken and simmer for 8 minutes.","Add the beans and pak choi and cook for 4 minutes until just tender and the chicken is cooked through.","Remove the lemongrass, stir in the fish sauce and lime juice, and serve with rice, topped with chilli and coriander."],
    tips:["Courgettes, peppers, peas and spinach all work well in place of the beans and pak choi.","Bash the lemongrass with a rolling pin before adding it so it releases its flavour."] },

  /* Sides */
  { id:"rosemary-roast-potatoes", title:"Crispy Roast Potatoes with Rosemary", time:"1 hr 15 min", serves:"4–6", uses:["potato","rosemary","garlic"],
    ingredients:[["potato","Floury potatoes, peeled and halved","1.5 kg"],["oil","Oil, goose fat or dripping","5 tbsp"],["rosemary","Rosemary sprigs","3"],["garlic","Garlic cloves, unpeeled and squashed","4"],["salt","Flaky salt","to taste"]],
    steps:["Heat the oven to 220°C (200°C fan) and put the oil in a large roasting tin to heat up.","Boil the potatoes in salted water for 10 minutes, then drain and leave to steam dry for 2 minutes.","Shake them in the pan to roughen the edges, which makes them crispy.","Carefully tip them into the hot oil and turn to coat. Roast for 30 minutes.","Turn them, add the rosemary and garlic, and roast for another 20 to 25 minutes until deep golden. Sprinkle with salt and serve."],
    tips:["Floury varieties such as Maris Piper, King Edward and Desiree roast best.","Make sure the oil is really hot before the potatoes go in, so they sizzle straight away."] },
  { id:"creamed-spinach", title:"Creamed Spinach", time:"15 min", serves:"4", uses:["spinach","garlic"],
    ingredients:[["spinach","Spinach","500 g"],["butter","Butter","25 g"],["garlic","Garlic clove, crushed","1"],["cream","Double cream or crème fraîche","100 ml"],["nutmeg","Grated nutmeg","pinch"]],
    steps:["Wash the spinach and put it in a large pan with just the water clinging to the leaves.","Cover and cook for 2 to 3 minutes until wilted, then drain and squeeze out as much liquid as you can. Chop roughly.","Melt the butter in the pan and cook the garlic for 30 seconds.","Add the spinach and cream and simmer for 2 to 3 minutes until thick.","Season with salt, pepper and a little nutmeg and serve."],
    tips:["A big pile of fresh spinach shrinks a lot, so use more than you think.","Chard and perpetual spinach both work well."] },
  { id:"minted-new-potatoes", title:"New Potatoes with Mint & Butter", time:"25 min", serves:"4", uses:["potato","mint","chives"],
    ingredients:[["potato","New potatoes, scrubbed","750 g"],["mint","Mint sprigs","3"],["butter","Butter","30 g"],["chives","Chives, snipped","small handful"],["salt","Flaky salt","to taste"]],
    steps:["Put the potatoes in a pan of cold salted water with 2 of the mint sprigs.","Bring to the boil and simmer for 12 to 15 minutes until a knife slides in easily.","Drain and return to the pan with the butter.","Chop the leaves from the last mint sprig and add them with the chives.","Toss gently, season with flaky salt and serve."],
    tips:["Freshly dug new potatoes need only a gentle scrub. The skins are thin and full of flavour.","Cook them as soon as you can after digging, when they are at their sweetest."] },
  { id:"french-beans-garlic-almonds", title:"French Beans with Garlic & Almonds", time:"15 min", serves:"4", uses:["french-bean","garlic"],
    ingredients:[["french-bean","French beans, topped","400 g"],["butter","Butter or olive oil","25 g"],["almonds","Flaked almonds","30 g"],["garlic","Garlic clove, thinly sliced","1"],["lemon","Lemon juice","squeeze"]],
    steps:["Cook the beans in boiling salted water for 3 to 4 minutes until just tender, then drain.","Meanwhile, melt the butter in a frying pan and toast the almonds for 2 minutes until golden.","Add the garlic and cook for 30 seconds.","Toss in the beans and lemon juice.","Season and serve straight away."],
    tips:["Runner beans, sliced thinly, work just as well.","Pick beans young and slim, before the seeds inside swell, for the best texture."] },
  { id:"peas-with-lettuce", title:"French-Style Peas with Lettuce", time:"15 min", serves:"4", uses:["pea","lettuce","spring-onion","mint"],
    ingredients:[["butter","Butter","25 g"],["spring-onion","Spring onions, sliced","4"],["pea","Peas, fresh or frozen","400 g"],["lettuce","Little gem lettuce, shredded","2 heads"],["stock","Vegetable or chicken stock","100 ml"],["mint","Mint, chopped (optional)","1 tbsp"]],
    steps:["Melt the butter in a pan and cook the spring onions for 2 minutes.","Add the peas and stock and simmer for 3 minutes.","Add the lettuce and cook for 2 minutes until just wilted.","Season with salt and pepper.","Stir in the mint if using and serve."],
    tips:["A good way to use lettuces that are starting to run to seed and taste a little bitter. Cooking softens the bitterness.","Freshly picked peas are so sweet they barely need cooking."] },

  /* Salads and starters */
  { id:"panzanella", title:"Tomato & Bread Salad (Panzanella)", time:"20 min", serves:"4", uses:["tomato","cucumber","onion","basil"],
    ingredients:[["bread","Day-old crusty bread, torn","200 g"],["tomato","Ripe tomatoes, chopped","600 g"],["cucumber","Cucumber, chopped","1/2"],["onion","Red onion, thinly sliced","1 small"],["olive oil","Olive oil","5 tbsp"],["vinegar","Red wine vinegar","2 tbsp"],["basil","Basil leaves","large handful"]],
    steps:["Put the tomatoes in a large bowl, sprinkle with salt and leave for 10 minutes to release their juices.","Toast the bread in a hot pan or oven with a little of the oil until crisp.","Add the cucumber, onion, the rest of the oil and the vinegar to the tomatoes.","Toss in the bread and basil and leave for 5 minutes so the bread soaks up the juices.","Season and serve."],
    tips:["Mix tomato varieties and colours to make it look as good as it tastes.","A great way to use slightly stale bread."] },
  { id:"greek-salad", title:"Greek Salad", time:"15 min", serves:"4", uses:["tomato","cucumber","onion","oregano"],
    ingredients:[["tomato","Ripe tomatoes, cut into chunks","4"],["cucumber","Cucumber, cut into chunks","1"],["onion","Red onion, thinly sliced","1 small"],["olives","Black olives","handful"],["feta","Feta cheese","200 g block"],["oregano","Oregano leaves (fresh or dried)","1 tsp"],["olive oil","Olive oil","4 tbsp"],["vinegar","Red wine vinegar","1 tbsp"]],
    steps:["Put the tomatoes, cucumber, onion and olives in a shallow bowl.","Whisk the oil and vinegar with a little salt and pepper and pour over.","Place the feta on top in one piece.","Sprinkle over the oregano and a little more oil.","Serve with crusty bread to mop up the juices."],
    tips:["Sliced green sweet pepper is a classic addition.","Soaking the onion in cold water for 10 minutes makes it milder."] },
  { id:"new-potato-salad", title:"New Potato Salad with Chives", time:"25 min", serves:"4", uses:["potato","chives","spring-onion"],
    ingredients:[["potato","New potatoes","750 g"],["mayonnaise","Mayonnaise","4 tbsp"],["yoghurt","Natural yoghurt","2 tbsp"],["mustard","Wholegrain mustard","1 tsp"],["spring-onion","Spring onions, sliced","3"],["chives","Chives, snipped","small handful"]],
    steps:["Boil the potatoes in salted water for 12 to 15 minutes until tender, then drain and leave to cool for 10 minutes.","Cut any larger potatoes in half.","Mix the mayonnaise, yoghurt and mustard together.","Fold the dressing through the warm potatoes with the spring onions and most of the chives.","Season and serve with the rest of the chives on top."],
    tips:["Dressing the potatoes while still warm helps them soak up the flavour.","Chopped mint, dill or parsley can be added too."] },
  { id:"garden-coleslaw", title:"Homemade Coleslaw", time:"15 min", serves:"6", uses:["cabbage","carrot","onion"],
    ingredients:[["cabbage","White or red cabbage, finely shredded","1/2 small"],["carrot","Carrots, grated","2"],["onion","Red onion or spring onions, finely sliced","1"],["mayonnaise","Mayonnaise","4 tbsp"],["yoghurt","Natural yoghurt","3 tbsp"],["lemon","Lemon juice","1 tbsp"],["mustard","Dijon mustard","1 tsp"]],
    steps:["Put the cabbage, carrots and onion in a large bowl.","Mix the mayonnaise, yoghurt, lemon juice and mustard.","Pour the dressing over the vegetables and mix well.","Season with salt and pepper.","Leave for 10 minutes before serving so it softens slightly."],
    tips:["Kohlrabi, apple, celeriac or beetroot can be grated in too.","Keeps in the fridge for 2 days."] },
  { id:"tomato-bruschetta", title:"Tomato Bruschetta", time:"15 min", serves:"4", uses:["tomato","basil","garlic"],
    ingredients:[["tomato","Ripe tomatoes, finely chopped","4"],["basil","Basil leaves, torn","small handful"],["olive oil","Olive oil","3 tbsp"],["vinegar","Balsamic vinegar (optional)","1 tsp"],["bread","Sourdough or ciabatta slices","8"],["garlic","Garlic clove, halved","1"]],
    steps:["Mix the tomatoes with the basil, 2 tbsp of the oil and the vinegar if using. Season well.","Toast or griddle the bread until golden and crisp.","Rub the cut side of the garlic over each warm toast.","Drizzle with the rest of the oil.","Pile the tomatoes on top just before serving."],
    tips:["Tip off any extra tomato juice before topping the toasts, so they stay crisp.","Small cherry tomatoes, quartered, are ideal."] },
  { id:"tabbouleh", title:"Herby Tabbouleh", time:"20 min", serves:"4", uses:["parsley","mint","tomato","cucumber","spring-onion"],
    ingredients:[["bulgur","Bulgur wheat","75 g"],["parsley","Flat-leaf parsley, finely chopped","2 large bunches"],["mint","Mint, finely chopped","small bunch"],["tomato","Tomatoes, finely diced","3"],["cucumber","Cucumber, finely diced","1/2"],["spring-onion","Spring onions, sliced","4"],["lemon","Lemon, juiced","1"],["olive oil","Olive oil","4 tbsp"]],
    steps:["Put the bulgur in a bowl, cover with boiling water and leave for 15 minutes. Drain well and cool.","Put the parsley, mint, tomatoes, cucumber and spring onions in a large bowl.","Add the bulgur.","Dress with the lemon juice and oil and season with salt and pepper.","Toss well and serve straight away."],
    tips:["This is really a herb salad with a little grain, so be generous with the parsley.","Chop the herbs with a sharp knife rather than a food processor, so they stay fresh and bright."] },

  /* Puddings and bakes */
  { id:"courgette-lemon-cake", title:"Courgette & Lemon Cake", time:"1 hr", serves:"10", uses:["courgette"],
    ingredients:[["courgette","Courgette, finely grated","250 g"],["oil","Sunflower oil","150 ml"],["egg","Eggs","3"],["sugar","Caster sugar","200 g"],["lemon","Lemons, zest and juice","2"],["flour","Self-raising flour","250 g"],["baking powder","Baking powder","1 tsp"],["icing sugar","Icing sugar","150 g"]],
    steps:["Heat the oven to 180°C (160°C fan) and line a 900 g loaf tin.","Squeeze some of the liquid out of the courgette.","Whisk the oil, eggs, sugar and lemon zest together, then stir in the courgette.","Fold in the flour and baking powder, pour into the tin and bake for 50 minutes until a skewer comes out clean.","Cool, then mix the icing sugar with enough lemon juice to make a thick icing and drizzle it over the cake."],
    tips:["The courgette keeps the cake moist without tasting of vegetables.","Freezes well without the icing."] },
  { id:"carrot-cake", title:"Carrot Cake", time:"1 hr 15 min", serves:"12", uses:["carrot"],
    ingredients:[["carrot","Carrots, grated","300 g"],["oil","Sunflower oil","200 ml"],["brown sugar","Light brown sugar","225 g"],["egg","Eggs","3"],["flour","Self-raising flour","250 g"],["spice","Mixed spice and cinnamon","1 tsp each"],["walnuts","Walnuts, chopped","75 g"],["orange","Orange zest","1"],["cream cheese","Cream cheese","200 g"],["butter","Butter, soft","50 g"],["icing sugar","Icing sugar","150 g"]],
    steps:["Heat the oven to 180°C (160°C fan) and grease and line a 20 cm round tin.","Whisk the oil, sugar and eggs together, then stir in the carrots, walnuts and orange zest.","Fold in the flour and spices, pour into the tin and bake for 55 minutes to 1 hour until a skewer comes out clean.","Leave to cool completely.","Beat the butter and icing sugar together, then beat in the cream cheese until smooth. Spread over the top of the cake."],
    tips:["Grate the carrots finely so they melt into the cake.","Keep the iced cake in the fridge, and take it out 30 minutes before serving."] },
  { id:"beetroot-brownies", title:"Beetroot Chocolate Brownies", time:"50 min", serves:"16 squares", uses:["beetroot"],
    ingredients:[["beetroot","Cooked beetroot, grated or blended","250 g"],["dark chocolate","Dark chocolate","200 g"],["butter","Butter","150 g"],["egg","Eggs","3"],["sugar","Caster sugar","200 g"],["flour","Plain flour","100 g"],["cocoa","Cocoa powder","25 g"]],
    steps:["Heat the oven to 180°C (160°C fan) and line a 20 cm square tin.","Melt the chocolate and butter together in a bowl over a pan of simmering water, then let it cool slightly.","Whisk the eggs and sugar until pale and thick, then fold in the chocolate mixture and the beetroot.","Fold in the flour and cocoa with a pinch of salt.","Pour into the tin and bake for 25 to 30 minutes until just set with a slight wobble in the middle. Cool in the tin before cutting."],
    tips:["To cook beetroot, boil it whole for 30 to 45 minutes until tender, then the skins rub off easily.","Brownies keep cooking as they cool, so take them out while the middle is still a little soft."] },
  { id:"dorset-apple-cake", title:"Dorset Apple Cake", time:"1 hr 10 min", serves:"8", uses:["apple"],
    ingredients:[["butter","Butter, soft","175 g"],["brown sugar","Light brown sugar","175 g"],["egg","Eggs","3"],["flour","Self-raising flour","225 g"],["spice","Ground cinnamon","1 tsp"],["milk","Milk","2 tbsp"],["apple","Cooking or eating apples, peeled and chopped","450 g"],["sugar","Demerara sugar, for the top","1 tbsp"]],
    steps:["Heat the oven to 180°C (160°C fan) and grease and line a 20 cm round tin.","Beat the butter and sugar together until light, then beat in the eggs one at a time.","Fold in the flour, cinnamon and milk, then stir in the apples.","Spoon into the tin, smooth the top and sprinkle with the demerara sugar.","Bake for 50 minutes to 1 hour until golden and a skewer comes out clean. Serve warm with cream or custard."],
    tips:["Good for apples from storage that have gone a little soft.","A handful of blackberries can go in with the apples."] },
  { id:"roast-rhubarb", title:"Roast Rhubarb with Orange", time:"25 min", serves:"4", uses:["rhubarb"],
    ingredients:[["rhubarb","Rhubarb stalks (never the leaves), cut into 5 cm pieces","500 g"],["orange","Orange, zest and juice","1"],["sugar","Caster sugar","3 tbsp"],["ginger","Ground ginger (optional)","pinch"]],
    steps:["Heat the oven to 200°C (180°C fan).","Arrange the rhubarb in a single layer in a baking dish.","Sprinkle with the sugar, orange zest and ginger, then pour over the orange juice.","Cover with foil and roast for 15 minutes.","Uncover and roast for another 5 minutes until tender but still holding its shape. Serve warm or cold with yoghurt, ice cream or custard."],
    tips:["Roasting keeps the pieces whole, unlike stewing.","Early forced rhubarb is the pinkest and most tender."] },
  { id:"pumpkin-pie", title:"Pumpkin Pie", time:"1 hr 30 min", serves:"8", uses:["pumpkin"],
    ingredients:[["pumpkin","Pumpkin or squash, peeled and cut into chunks","750 g"],["pastry","Ready-rolled shortcrust pastry","320 g sheet"],["brown sugar","Light brown sugar","140 g"],["spice","Ground cinnamon, ginger and nutmeg","1 tsp, 1/2 tsp, 1/2 tsp"],["egg","Eggs","2"],["butter","Butter, melted","25 g"],["milk","Milk","175 ml"]],
    steps:["Steam or boil the pumpkin for 15 minutes until soft. Drain well, leave to cool and blend to a smooth purée. You need about 450 g.","Heat the oven to 200°C (180°C fan). Line a 22 cm tart tin with the pastry and bake for 15 minutes.","Whisk the pumpkin with the sugar, spices, eggs, melted butter and milk.","Pour into the pastry case and turn the oven down to 180°C (160°C fan).","Bake for 35 to 40 minutes until just set with a slight wobble. Cool before slicing."],
    tips:["Dense, sweet squash such as butternut or crown prince gives a better result than large carving pumpkins.","Drain the cooked pumpkin really well, or the filling will be watery."] },
  { id:"blueberry-muffins", title:"Blueberry Muffins", time:"35 min", serves:"12", uses:["blueberry"],
    ingredients:[["flour","Self-raising flour","300 g"],["baking powder","Baking powder","1 tsp"],["sugar","Caster sugar","150 g"],["egg","Eggs","2"],["milk","Milk","150 ml"],["oil","Sunflower oil or melted butter","100 ml"],["lemon","Lemon zest","1"],["blueberry","Blueberries","200 g"]],
    steps:["Heat the oven to 200°C (180°C fan) and line a 12-hole muffin tin with cases.","Mix the flour, baking powder and sugar in a large bowl.","Whisk the eggs, milk, oil and lemon zest together in a jug.","Pour the wet mixture into the dry and stir until only just combined, then fold in the blueberries.","Divide between the cases and bake for 20 to 25 minutes until risen and golden."],
    tips:["Do not over-mix. A lumpy batter makes lighter muffins.","Frozen blueberries work well. Add them straight from the freezer."] },

  /* Preserves and sauces */
  { id:"roast-tomato-sauce", title:"Roast Tomato Pasta Sauce for the Freezer", time:"1 hr 15 min", serves:"makes about 1.5 litres", uses:["tomato","onion","garlic","basil"],
    ingredients:[["tomato","Ripe tomatoes, halved","2 kg"],["onion","Onions, cut into wedges","2"],["garlic","Garlic cloves, peeled","6"],["olive oil","Olive oil","4 tbsp"],["sugar","Sugar","1 tsp"],["basil","Basil leaves","large handful"]],
    steps:["Heat the oven to 200°C (180°C fan). Spread the tomatoes, onions and garlic over two roasting tins, drizzle with the oil and season.","Roast for 45 minutes to 1 hour until soft, sticky and lightly charred.","Tip everything into a large pan, add the sugar and basil, and blend until smooth or leave chunky.","Simmer for 10 minutes to thicken if it seems thin.","Cool, then freeze in bags or tubs for up to 6 months."],
    tips:["Freeze it flat in bags so it thaws quickly.","Use it for pasta, pizza, lasagne or as a base for soup."] },
  { id:"green-tomato-chutney", title:"Green Tomato Chutney", time:"2 hr", serves:"makes about 4 jars", uses:["tomato","onion","apple"],
    ingredients:[["tomato","Green tomatoes, chopped","1 kg"],["onion","Onions, chopped","500 g"],["apple","Cooking apples, peeled and chopped","500 g"],["raisins","Sultanas or raisins","200 g"],["brown sugar","Light brown sugar","350 g"],["vinegar","Malt or cider vinegar","500 ml"],["spice","Mustard seeds and ground ginger","1 tsp each"],["salt","Salt","1 tsp"]],
    steps:["Put everything in a large, heavy pan and stir over a low heat until the sugar dissolves.","Bring to the boil, then simmer gently for 1 hour 30 minutes, stirring more often towards the end so it does not stick.","It is ready when it is thick and a spoon dragged across the bottom of the pan leaves a clear trail for a few seconds.","Spoon into hot, clean jars and seal straight away.","Store in a cool, dark place for at least a month before eating, so the flavours mellow. Keeps for up to a year unopened. Once opened, keep in the fridge."],
    tips:["The perfect use for the last tomatoes that will not ripen before the frost.","Use a stainless steel or enamel pan, not aluminium, as vinegar reacts with it."] },
  { id:"runner-bean-chutney", title:"Runner Bean Chutney", time:"1 hr 30 min", serves:"makes about 4 jars", uses:["bean","onion"],
    ingredients:[["bean","Runner beans, trimmed and sliced","1 kg"],["onion","Onions, chopped","500 g"],["vinegar","Malt vinegar","600 ml"],["sugar","Granulated sugar","600 g"],["cornflour","Cornflour","1 tbsp"],["spice","Mustard powder and ground turmeric","1 tbsp each"],["salt","Salt","1 tsp"]],
    steps:["Cook the onions in 300 ml of the vinegar for 15 minutes until soft.","Meanwhile, boil the beans in salted water for 5 minutes, then drain.","Add the beans, sugar and most of the remaining vinegar to the onions and stir until the sugar dissolves. Simmer for 15 minutes.","Mix the cornflour, mustard and turmeric with the last of the vinegar to make a paste, stir it in and simmer for 15 minutes more, stirring, until thick.","Spoon into hot, clean jars, seal and leave for 2 weeks before eating. Keep opened jars in the fridge."],
    tips:["Older, slightly stringy beans are fine here. Just string them before slicing.","Lovely with cheese, cold meats and in sandwiches."] },
  { id:"strawberry-jam", title:"Strawberry Jam", time:"45 min", serves:"makes about 4 jars", uses:["strawberry"],
    ingredients:[["strawberry","Strawberries, hulled and halved","1 kg"],["sugar","Jam sugar (with added pectin)","1 kg"],["lemon","Lemon, juiced","1"],["butter","Butter (optional)","small knob"]],
    steps:["Put two saucers in the freezer. Put the strawberries in a large pan, lightly crush some of them and add the lemon juice.","Heat gently until the juices run, then add the sugar and stir over a low heat until it has completely dissolved.","Turn up the heat and boil hard for 4 to 5 minutes.","Test for a set: drop a little jam onto a cold saucer, wait 1 minute and push it with your finger. If it wrinkles, it is ready. If not, boil for 2 more minutes and test again.","Stir in the butter to clear any scum, leave for 15 minutes so the fruit does not sink, then pour into hot, clean jars and seal."],
    tips:["Strawberries are low in pectin, the natural setting agent, so jam sugar gives a much more reliable set.","Slightly under-ripe berries set better than very soft ones."] },
  { id:"mint-sauce", title:"Fresh Mint Sauce", time:"10 min", serves:"4", uses:["mint"],
    ingredients:[["mint","Mint leaves","large handful (about 20 g)"],["sugar","Caster sugar","1 tbsp"],["water","Boiling water","2 tbsp"],["vinegar","White wine or malt vinegar","3 tbsp"]],
    steps:["Chop the mint very finely with a pinch of salt.","Put it in a small bowl with the sugar.","Pour over the boiling water and stir until the sugar dissolves.","Stir in the vinegar.","Leave for 10 minutes before serving with roast lamb, peas or new potatoes."],
    tips:["Garden mint or spearmint give the classic flavour.","Mint sauce keeps for a week in the fridge."] },
  { id:"chilli-jam", title:"Sweet Chilli Jam", time:"1 hr", serves:"makes about 3 jars", uses:["chilli","sweet-pepper","garlic"],
    ingredients:[["sweet-pepper","Red sweet peppers, deseeded and chopped","4"],["chilli","Red chillies, chopped","8–10"],["garlic","Garlic cloves","4"],["ginger","Fresh ginger","thumb-sized piece"],["sugar","Jam sugar (with added pectin)","750 g"],["vinegar","Red wine or cider vinegar","250 ml"]],
    steps:["Blitz the peppers, chillies, garlic and ginger in a food processor until finely chopped.","Put in a large pan with the sugar and vinegar and stir over a low heat until the sugar dissolves.","Bring to the boil and simmer for 40 to 50 minutes, stirring now and then, until sticky and glossy.","It is ready when it coats a spoon and looks like runny honey. It thickens more as it cools.","Leave to cool for 10 minutes, stir to spread the pieces evenly, then pour into hot, clean jars and seal."],
    tips:["Keep some chilli seeds in for more heat, or take them all out for a milder jam.","Wear gloves when chopping chillies and keep your hands away from your eyes."] },
  { id:"garlic-herb-butter", title:"Garlic & Herb Butter", time:"10 min", serves:"makes about 250 g", uses:["garlic","parsley","chives"],
    ingredients:[["butter","Butter, softened","250 g"],["garlic","Garlic cloves, crushed","3–4"],["parsley","Parsley, finely chopped","3 tbsp"],["chives","Chives, finely snipped","2 tbsp"],["lemon","Lemon zest","1/2"]],
    steps:["Beat the butter until soft.","Mix in the garlic, herbs and lemon zest with a pinch of salt.","Spoon onto a sheet of baking paper and roll into a log.","Twist the ends and chill until firm.","Slice off rounds to melt over steak, fish, vegetables or into garlic bread. Keeps for 2 weeks in the fridge or 3 months in the freezer."],
    tips:["A great way to preserve soft herbs before the frost. Tarragon, dill or chervil also work.","Freeze the log already sliced, so you can take out just what you need."] },

  /* Breakfast and snacks */
  { id:"sweetcorn-fritters", title:"Sweetcorn Fritters", time:"25 min", serves:"4", uses:["sweetcorn","spring-onion","chilli","coriander"],
    ingredients:[["sweetcorn","Sweetcorn kernels, cut from 3 cobs","about 300 g"],["flour","Self-raising flour","100 g"],["egg","Eggs","2"],["milk","Milk","75 ml"],["spring-onion","Spring onions, sliced","3"],["chilli","Red chilli, chopped","1"],["coriander","Coriander, chopped","small handful"],["oil","Oil for frying","3 tbsp"]],
    steps:["Whisk the flour, eggs and milk into a thick batter.","Stir in the sweetcorn, spring onions, chilli and coriander and season.","Heat a little oil in a frying pan over a medium heat.","Drop in spoonfuls of the batter and fry for 2 to 3 minutes on each side until golden.","Drain on kitchen paper and serve with avocado, bacon or a poached egg."],
    tips:["To cut the kernels off, stand a cob upright in a wide bowl and run a sharp knife down the sides.","Frozen sweetcorn works too. Defrost and pat it dry first."] },
  { id:"kale-crisps", title:"Kale Crisps", time:"25 min", serves:"4", uses:["kale"],
    ingredients:[["kale","Kale, stalks removed, torn into pieces","150 g"],["olive oil","Olive oil","1 tbsp"],["salt","Salt","pinch"],["paprika","Smoked paprika (optional)","1/2 tsp"]],
    steps:["Heat the oven to 150°C (130°C fan).","Make sure the kale is completely dry, then rub it all over with the oil.","Spread over two baking trays in a single layer, so the pieces do not touch.","Bake for 15 to 20 minutes until crisp but still green.","Sprinkle with salt and paprika and eat straight away."],
    tips:["Curly kale gives the crunchiest crisps.","Watch them closely near the end. They go from crisp to burnt quickly."] },
  { id:"roast-pumpkin-seeds", title:"Roasted Pumpkin Seeds", time:"30 min", serves:"4", uses:["pumpkin"],
    ingredients:[["pumpkin","Seeds from 1 pumpkin or squash","about 100 g"],["olive oil","Olive oil","1 tsp"],["salt","Salt","pinch"],["spice","Paprika, cumin or cinnamon (optional)","1/2 tsp"]],
    steps:["Heat the oven to 160°C (140°C fan).","Rinse the seeds in a sieve, pulling off the stringy flesh, then dry them well on a tea towel.","Toss with the oil, salt and any spice.","Spread over a baking tray in a single layer.","Roast for 15 to 20 minutes, stirring halfway, until golden and crisp. Cool before eating."],
    tips:["Smaller seeds from squashes roast quicker and are crunchier than large pumpkin seeds.","Sprinkle over soups and salads, or eat as a snack."] },

  /* Drinks */
  { id:"fresh-mint-tea", title:"Fresh Mint Tea", time:"5 min", serves:"2", uses:["mint"],
    ingredients:[["mint","Fresh mint sprigs","a large handful"],["water","Boiling water","500 ml"],["honey","Honey (optional)","to taste"]],
    steps:["Rinse the mint and put it in a teapot or jug.","Pour over the water, just off the boil.","Leave to steep for 5 minutes.","Pour into cups, adding a fresh leaf to each.","Sweeten with honey if you like."],
    tips:["Bruise the leaves gently in your hand first to release more flavour.","Try mixing in lemon balm or lemon verbena."] },
  { id:"elderflower-cordial", title:"Elderflower Cordial", time:"30 min + 24 hr", serves:"makes about 1.5 litres", uses:["elderberry"],
    ingredients:[["elderberry","Elderflower heads, fully open","20"],["sugar","Granulated sugar","1 kg"],["water","Water","1 litre"],["lemon","Unwaxed lemons, sliced","2"],["citric acid","Citric acid (from chemists or online)","25 g"]],
    steps:["Shake the flower heads to remove insects. Do not wash them, as this removes the pollen that gives the flavour.","Heat the sugar and water in a large pan, stirring until the sugar dissolves, then bring to the boil and take off the heat.","Add the lemon slices, citric acid and flower heads, pushing them under the syrup.","Cover with a tea towel and leave for 24 hours.","Strain through muslin into clean bottles. Dilute about 1 part cordial to 6 parts water. Keeps for 6 weeks in the fridge, or freeze in plastic bottles."],
    tips:["Pick flowers on a dry, sunny morning when they smell sweet and creamy. Avoid any that smell musty.","Pick from roadsides only well away from traffic, and leave some flowers so you get elderberries in autumn."] },
];
